func runReminder(t *testing.T, s *store.Store, now time.Time, wantCode int, wantOutput string) {
    t.Helper()
    writeFixture(t, s)
    var out, diagnostics bytes.Buffer
    code := run([]string{"remind", "--now", now.Format(time.RFC3339Nano)}, &out, &diagnostics)
    if code != wantCode || out.String() != wantOutput {
        t.Fatalf("got exit %d, stdout %q, stderr %q; want exit %d, stdout %q", code, out.String(), diagnostics.String(), wantCode, wantOutput)
    }
    if wantCode == 0 && diagnostics.Len() != 0 { t.Fatalf("unexpected stderr: %s", &diagnostics) }
}

func readMessages(t *testing.T, outbox string) []smsMessage {
    t.Helper()
    paths, err := filepath.Glob(filepath.Join(outbox, "sms", "*.json"))
    if err != nil { t.Fatal(err) }
    var messages []smsMessage
    for _, path := range paths {
        var doc struct {
            Destination string `json:"destination"`
            Body smsMessage `json:"body"`
        }
        if err := loadReminderJSON(path, &doc); err != nil { t.Fatal(err) }
        if doc.Destination != "sms" { t.Fatalf("destination %q", doc.Destination) }
        messages = append(messages, doc.Body)
    }
    return messages
}

