type failOneSender struct { calls []string }
func (f *failOneSender) Send(destination string, body any) error {
    message := body.(smsMessage)
    f.calls = append(f.calls, destination+":"+message.Reference)
    if message.Reference == "appt-a" { return notify.DeliveryError{Destination: destination, Reason: "test failure"} }
    return nil
}

