    s, outbox := reminderFixture(t)
    now := mustTime(t, "2026-11-16T10:00:00Z")
    s.Appointments = []store.Appointment{appt("a", now.Add(time.Hour))}
    start := make(chan struct{})
    type result struct { output string; err error }
    results := make(chan result, 2)
    for i := 0; i < 2; i++ {
        go func() {
            <-start
            var out, diagnostics bytes.Buffer
            err := remind(s, []string{"--now", now.Format(time.RFC3339)}, &out, &diagnostics, notify.NewClient())
            results <- result{out.String(), err}
        }()
    }
    close(start)
    counts := map[string]int{}
    for i := 0; i < 2; i++ {
        r := <-results
        if r.err != nil { t.Fatal(r.err) }
        counts[r.output]++
    }
    if counts["reminded a\nsent 1\n"] != 1 || counts["sent 0\n"] != 1 || len(readMessages(t, outbox)) != 1 {
        t.Fatalf("overlapping runs: %#v", counts)
    }
}
